for ci in range(3):
  for e in range(6):
    m=np.where((c==ci)&(ep==e))[0]
    emp=X[m][:,vis].sum(1)==0
    # longest run of all-empty states and when it starts
    runs=[];r=0;st=None
    for k in range(len(m)):
        if emp[k]:
            if r==0: st=t[m[k]]
            r+=1
        else:
            if r>0: runs.append((r*5,st)); r=0
    if r>0: runs.append((r*5,st))
    runs.sort(reverse=True)
    print(ci,e,'end',t[m].max(),'n empty states',emp.sum(),'longest empty runs (s,start)',runs[:3])
"

